  Lemma lit_keepalive_bytes : forall m, mem_inv bsegs m -> bytes_at bsegs m ALIT_KEEPALIVE LITB_KEEPALIVE.
  Proof.
    intros m MI. apply (ro_cells_bytes_at bsegs m ALIT_KEEPALIVE [CB 10 LITB_KEEPALIVE]).
    apply (ro_cells_image bsegs m); [exact MI | vm_compute; reflexivity | unfold ALIT_KEEPALIVE; lia | cbn; unfold ALIT_KEEPALIVE; lia].
  Qed.
  Lemma lit_upgrade_bytes : forall m, mem_inv bsegs m -> bytes_at bsegs m ALIT_UPGRADE LITB_UPGRADE.
  Proof.
    intros m MI. apply (ro_cells_bytes_at bsegs m ALIT_UPGRADE [CB 7 LITB_UPGRADE]).
    apply (ro_cells_image bsegs m); [exact MI | vm_compute; reflexivity | unfold ALIT_UPGRADE; lia | cbn; unfold ALIT_UPGRADE; lia].
  Qed.
  Lemma lit_chunked_bytes : forall m, mem_inv bsegs m -> bytes_at bsegs m ALIT_CHUNKED LITB_CHUNKED.
  Proof.
    intros m MI. apply (ro_cells_bytes_at bsegs m ALIT_CHUNKED [CB 7 LITB_CHUNKED]).
    apply (ro_cells_image bsegs m); [exact MI | vm_compute; reflexivity | unfold ALIT_CHUNKED; lia | cbn; unfold ALIT_CHUNKED; lia].
  Qed.
  Lemma clmax_ro : forall m, mem_inv bsegs m -> ro_cells bsegs m A_CLMAX10 [CB 8 LITB_CLMAX].
  Proof.
    intros m MI. apply (ro_cells_image bsegs m); [exact MI | vm_compute; reflexivity | unfold A_CLMAX10; lia | cbn; unfold A_CLMAX10; lia].
  Qed.

