  Lemma dwin_pwin : forall LF m0 m lo shi ff fp P E vp n iv,
    dof_side LF m0 m lo shi ff fp P E vp n -> dwin ff P E iv -> pwin iv.
  Proof.
    intros LF m0 m lo shi ff fp P E vp n [l h] SD D.
    destruct (dof_ff_nums _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & _). destruct SD as (_ & _ & APP & APE & _).
    destruct D as [K|[[K1 K2]|[[K1 K2]|[[K1 K2]|K]]]]; cbn [fst snd] in *.
    - apply pwin_stack. exact K.
    - eapply pwin_aapp; [exact APF| exact K1| exact K2].
    - eapply pwin_aapp; [exact APP| exact K1| exact K2].
    - eapply pwin_aapp; [exact APE| exact K1| exact K2].
    - rewrite K. apply pwin_httpcat.
  Qed.
