Lemma sub_fp_incl : forall W W' : list (Z * Z),
  Forall (fun w => Exists (fun v => fst v <= fst w /\ snd w <= snd v) W') W -> sub_fp W W'.
Proof.
  induction W as [|[l h] W IH]; intros W' FA x OUT; cbn; [exact I|].
  pose proof (Forall_inv FA) as EX. pose proof (Forall_inv_tail FA) as FA'. cbn [fst snd] in EX.
  split; [| exact (IH W' FA' x OUT)].
  clear IH FA FA'. induction W' as [|[l' h'] W' IH']; [inversion EX|].
  cbn in OUT. destruct OUT as [O1 OUT]. inversion EX; subst.
  - cbn [fst snd] in *. lia.
  - apply IH'; assumption.
Qed.
Lemma munch_compose : forall (Wt W1 : list (Z * Z)) m m1 m2,
  munch Wt m m1 -> munch W1 m1 m2 ->
  Forall (fun w => Exists (fun v => fst v <= fst w /\ snd w <= snd v) Wt) W1 -> munch Wt m m2.
Proof.
  intros Wt W1 m m1 m2 MU MU1 FA. eapply munch_trans; [exact MU|]. eapply munch_weaken; [| exact MU1]. apply sub_fp_incl. exact FA.
Qed.
