Ltac cb_split H k H2 :=
  let H1 := fresh "CBL" in
  lazymatch type of H with
  | rw_cells _ _ (?b + ?o) [CB ?n _] =>
    let nk := eval vm_compute in (n - k)%nat in
    let o2 := eval vm_compute in (o + Z.of_nat k)%Z in
    destruct (rw_cells_CB_split bsegs _ _ n k _ H ltac:(lia)) as [H1 H2]; clear H; rename H1 into H;
    change (n - k)%nat with nk in H2;
    replace (b + o + Z.of_nat k)%Z with (b + o2)%Z in H2 by lia
  | rw_cells _ _ ?b [CB ?n _] =>
    let nk := eval vm_compute in (n - k)%nat in
    let o2 := eval vm_compute in (Z.of_nat k) in
    destruct (rw_cells_CB_split bsegs _ _ n k _ H ltac:(lia)) as [H1 H2]; clear H; rename H1 into H;
    change (n - k)%nat with nk in H2;
    change (Z.of_nat k) with o2 in H2
  end.
Ltac blob2 H1 H2 :=
  let j1 := fresh "jb" in let j2 := fresh "jb" in let B1 := fresh "BL" in let B2 := fresh "BL" in
  destruct (rw_cells_forget _ _ _ _ H1) as [j1 B1]; destruct (rw_cells_forget _ _ _ _ H2) as [j2 B2]; clear H1 H2;
  cbn [cells_size csize Nat.add TokItCells OptItCells map] in B1, B2;
  lazymatch type of B1 with rw_cells _ _ ?a1 [CB ?n1 _] =>
    lazymatch type of B2 with rw_cells _ _ ?a2 _ =>
      replace a2 with (a1 + Z.of_nat n1)%Z in B2 by lia;
      pose proof (rw_cells_CB_join bsegs _ _ _ _ _ _ B1 B2) as H1; clear B1 B2; cbn [Nat.add app] in H1
    end end.
